// ---------------------------------------------------------------- helpers

/// The digest of SPEC section 2, written out once more for the tests.
fn fnv(bytes: &[u8]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for &byte in bytes {
        hash = (hash ^ u64::from(byte)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn entry(digest: u64, name: &str) -> Entry {
    Entry {
        digest,
        name: name.to_string(),
    }
}

/// A reader that gives at most `step` bytes per call. If `interrupt` is
/// set, every second call fails with `Interrupted` and gives nothing.
struct Trickle<'a> {
    data: &'a [u8],
    step: usize,
    interrupt: bool,
    calls: usize,
}

impl Read for Trickle<'_> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        self.calls += 1;
        if self.interrupt && self.calls % 2 == 1 {
            return Err(io::Error::new(ErrorKind::Interrupted, "try again"));
        }
        let count = self.step.min(buf.len()).min(self.data.len());
        buf[..count].copy_from_slice(&self.data[..count]);
        self.data = &self.data[count..];
        Ok(count)
    }
}

/// A reader that gives `data` and then fails with an error of `kind`.
struct Broken<'a> {
    data: &'a [u8],
    kind: ErrorKind,
}

impl Read for Broken<'_> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.data.is_empty() {
            return Err(io::Error::new(self.kind, "the device failed"));
        }
        let count = buf.len().min(self.data.len()).min(5);
        buf[..count].copy_from_slice(&self.data[..count]);
        self.data = &self.data[count..];
        Ok(count)
    }
}

/// A writer that accepts at most three bytes per call. If `interrupt` is
/// set, every second call fails with `Interrupted` and accepts nothing.
#[derive(Default)]
struct Stingy {
    written: Vec<u8>,
    interrupt: bool,
    calls: usize,
    flushes: usize,
}

impl Write for Stingy {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        self.calls += 1;
        if self.interrupt && self.calls % 2 == 1 {
            return Err(io::Error::new(ErrorKind::Interrupted, "try again"));
        }
        let count = buf.len().min(3);
        self.written.extend_from_slice(&buf[..count]);
        Ok(count)
    }

    fn flush(&mut self) -> io::Result<()> {
        self.flushes += 1;
        Ok(())
    }
}

/// A writer that fails once `room` bytes have been written.
struct Full {
    room: usize,
    kind: Option<ErrorKind>,
}

impl Write for Full {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        if self.room == 0 {
            return match self.kind {
                Some(kind) => Err(io::Error::new(kind, "no more room")),
                None => Ok(0),
            };
        }
        let count = buf.len().min(self.room);
        self.room -= count;
        Ok(count)
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

