// ----------------------------------------------------------------- digest

#[test]
fn digest_of_known_inputs() {
    assert_eq!(
        digest(&b""[..]).unwrap(),
        0xcbf2_9ce4_8422_2325,
        "the digest of no bytes is the start value"
    );
    assert_eq!(digest(&b"a"[..]).unwrap(), 0xaf63_dc4c_8601_ec8c);
    assert_eq!(digest(&b"foobar"[..]).unwrap(), 0x8594_4171_f739_67e8);
    assert_eq!(digest(&b"hello\n"[..]).unwrap(), 0xa9bc_80cc_a21f_28b3);
    assert_eq!(digest("Zoë".as_bytes()).unwrap(), 0x17a3_b76d_1a6f_5cbc);
    assert_ne!(digest(&b"abc"[..]).unwrap(), digest(&b"abd"[..]).unwrap());
}

#[test]
fn digest_of_a_megabyte() {
    let data: Vec<u8> = (0..=255u8).cycle().take(1 << 20).collect();
    assert_eq!(digest(Cursor::new(&data)).unwrap(), 0x8505_ae44_3552_2325);
    assert_eq!(
        digest(&vec![b'x'; 1_000_000][..]).unwrap(),
        0xc5a9_9129_16bf_6025
    );
}

#[test]
fn digest_accepts_short_reads() {
    let data: Vec<u8> = (0..=255u8).cycle().take(10_000).collect();
    for step in [1, 2, 7, 4096, 9999] {
        let reader = Trickle {
            data: &data,
            step,
            interrupt: false,
            calls: 0,
        };
        assert_eq!(
            digest(reader).unwrap(),
            fnv(&data),
            "with at most {step} byte(s) per read. A read that gives fewer bytes than the \
             buffer holds is not the end; only Ok(0) is."
        );
    }
}

#[test]
fn digest_retries_interrupted_reads() {
    let data = b"interrupted again and again";
    let reader = Trickle {
        data,
        step: 4,
        interrupt: true,
        calls: 0,
    };
    assert_eq!(
        digest(reader).ok(),
        Some(fnv(data)),
        "a read that fails with ErrorKind::Interrupted has read nothing and must be repeated"
    );
}

#[test]
fn digest_returns_other_errors() {
    for kind in [
        ErrorKind::PermissionDenied,
        ErrorKind::UnexpectedEof,
        ErrorKind::Other,
    ] {
        let reader = Broken {
            data: b"twelve bytes",
            kind,
        };
        assert_eq!(digest(reader).map_err(|error| error.kind()), Err(kind));
    }
    let at_once = Broken {
        data: b"",
        kind: ErrorKind::NotFound,
    };
    assert_eq!(
        digest(at_once).map_err(|error| error.kind()),
        Err(ErrorKind::NotFound)
    );
}

#[test]
fn digest_takes_any_reader() {
    let mut cursor = Cursor::new(b"foobar".to_vec());
    assert_eq!(digest(&mut cursor).unwrap(), 0x8594_4171_f739_67e8);
    assert_eq!(
        digest(&mut cursor).unwrap(),
        0xcbf2_9ce4_8422_2325,
        "the cursor is at its end now"
    );
    let chained = (&b"foo"[..]).chain(&b"bar"[..]);
    assert_eq!(digest(chained).unwrap(), 0x8594_4171_f739_67e8);
    let boxed: Box<dyn Read> = Box::new(&b"a"[..]);
    assert_eq!(digest(boxed).unwrap(), 0xaf63_dc4c_8601_ec8c);
}

// ---------------------------------------------------------------- display

#[test]
fn display_writes_digest_two_spaces_and_name() {
    assert_eq!(
        entry(0xaf63_dc4c_8601_ec8c, "notes/a.txt").to_string(),
        "af63dc4c8601ec8c  notes/a.txt"
    );
    assert_eq!(
        entry(255, "x").to_string(),
        "00000000000000ff  x",
        "16 digits with leading zeros"
    );
    assert_eq!(entry(0, "x").to_string(), "0000000000000000  x");
    assert_eq!(entry(u64::MAX, "x").to_string(), "ffffffffffffffff  x");
    assert_eq!(
        entry(0xABCD_EF00_0000_0000, "x").to_string(),
        "abcdef0000000000  x",
        "the digits a to f are written in lower case"
    );
}

#[test]
fn display_keeps_ordinary_characters() {
    for name in [
        "photos/Zoë in Århus.jpg",
        "  two spaces in front",
        "trailing space ",
        "tab\there",
        "李/雷.txt",
        "quote\"and'apostrophe",
        "/",
        "🦀",
    ] {
        assert_eq!(
            entry(1, name).to_string(),
            format!("0000000000000001  {name}")
        );
    }
}

#[test]
fn display_escapes_backslash_and_line_endings() {
    assert_eq!(
        entry(255, "a\\b").to_string(),
        "00000000000000ff  a\\\\b",
        "one backslash in the name is two in the line"
    );
    assert_eq!(
        entry(1, "one\ntwo\rthree").to_string(),
        "0000000000000001  one\\ntwo\\rthree"
    );
    assert_eq!(
        entry(1, "\\\\\n\n\r\\").to_string(),
        "0000000000000001  \\\\\\\\\\n\\n\\r\\\\"
    );
    assert_eq!(
        entry(1, "\\n").to_string(),
        "0000000000000001  \\\\n",
        "a backslash and the letter n in the name are three characters in the line"
    );
    let line = entry(1, "é\\é\né").to_string();
    assert_eq!(line, "0000000000000001  é\\\\é\\né");
    assert!(
        !line.contains(['\n', '\r']),
        "a line never contains a line feed or a carriage return"
    );
}

// ---------------------------------------------------------------- parsing

#[test]
fn parse_a_line() {
    assert_eq!(
        "af63dc4c8601ec8c  notes/a.txt".parse(),
        Ok(entry(0xaf63_dc4c_8601_ec8c, "notes/a.txt"))
    );
    assert_eq!("00000000000000ff  x".parse(), Ok(entry(255, "x")));
    assert_eq!("ffffffffffffffff  x".parse(), Ok(entry(u64::MAX, "x")));
}

#[test]
fn parse_accepts_upper_case_digits() {
    assert_eq!(
        "AF63DC4C8601EC8C  x".parse(),
        Ok(entry(0xaf63_dc4c_8601_ec8c, "x"))
    );
    assert_eq!(
        "aBcDeF0123456789  x".parse(),
        Ok(entry(0xabcd_ef01_2345_6789, "x"))
    );
}

#[test]
fn parse_takes_the_rest_of_the_line_as_the_name() {
    let name = |line: &str| line.parse::<Entry>().map(|entry| entry.name);
    assert_eq!(
        name("0000000000000001   x"),
        Ok(" x".to_string()),
        "a third space is the first character of the name"
    );
    assert_eq!(name("0000000000000001  x  "), Ok("x  ".to_string()));
    assert_eq!(name("0000000000000001    "), Ok("  ".to_string()));
    assert_eq!(name("0000000000000001  \t"), Ok("\t".to_string()));
    assert_eq!(
        name("0000000000000001  photos/Zoë in Århus.jpg"),
        Ok("photos/Zoë in Århus.jpg".to_string())
    );
    assert_eq!(
        name("0000000000000001  0000000000000002  y"),
        Ok("0000000000000002  y".to_string())
    );
}

#[test]
fn parse_reads_escapes() {
    let name = |line: &str| line.parse::<Entry>().map(|entry| entry.name);
    assert_eq!(name("0000000000000001  a\\\\b"), Ok("a\\b".to_string()));
    assert_eq!(
        name("0000000000000001  one\\ntwo\\rthree"),
        Ok("one\ntwo\rthree".to_string())
    );
    assert_eq!(
        name("0000000000000001  \\\\n"),
        Ok("\\n".to_string()),
        "read from the left: `\\\\` is a backslash, and the `n` after it is a plain letter"
    );
    assert_eq!(name("0000000000000001  \\\\\\n"), Ok("\\\n".to_string()));
    assert_eq!(name("0000000000000001  \\\\\\\\"), Ok("\\\\".to_string()));
    assert_eq!(name("0000000000000001  \\n"), Ok("\n".to_string()));
    assert_eq!(
        name("0000000000000001  é\\\\é\\né"),
        Ok("é\\é\né".to_string())
    );
}

#[test]
fn parse_digest_errors() {
    let bad = [
        "",
        "abc",
        "0",
        "  x",
        "000000000000000  x",
        "000000000000000g  x",
        "0x00000000000000  x",
        "+000000000000001  x",
        "-000000000000001  x",
        " 000000000000001  x",
        "0000 0000 0000 0001  x",
        "00000000_0000001  x",
        "000000000000000\u{e9}  x",
        "00000000000000\u{e9}  x",
        "\u{663}\u{663}\u{663}\u{663}\u{663}\u{663}\u{663}\u{663}  x",
        "\u{ff10}000000000000000  x",
        "🦀🦀🦀🦀  x",
    ];
    for line in bad {
        assert_eq!(
            line.parse::<Entry>(),
            Err(EntryError::Digest),
            "{line:?} does not start with 16 of the characters 0-9, a-f, A-F"
        );
    }
}

#[test]
fn parse_separator_errors() {
    let bad = [
        "0000000000000001",
        "0000000000000001 ",
        "0000000000000001 x",
        "0000000000000001x",
        "0000000000000001\t\tx",
        "0000000000000001 \tx",
        "00000000000000012  x",
        "0000000000000001\u{a0}\u{a0}x",
        "0000000000000001é",
    ];
    for line in bad {
        assert_eq!(
            line.parse::<Entry>(),
            Err(EntryError::Separator),
            "{line:?}: exactly two spaces must follow the 16 digits"
        );
    }
}

#[test]
fn parse_name_and_escape_errors() {
    assert_eq!("0000000000000001  ".parse::<Entry>(), Err(EntryError::Name));
    let escape = |line: &str| line.parse::<Entry>().err();
    assert_eq!(
        escape("0000000000000001  ab\\q"),
        Some(EntryError::Escape(20)),
        "the backslash is at byte 20 of the line: 16 digits, 2 spaces, then `ab`"
    );
    assert_eq!(
        escape("0000000000000001  abc\\"),
        Some(EntryError::Escape(21)),
        "a backslash at the end of the line has nothing to escape"
    );
    assert_eq!(escape("0000000000000001  \\"), Some(EntryError::Escape(18)));
    assert_eq!(
        escape("0000000000000001  \\N"),
        Some(EntryError::Escape(18))
    );
    assert_eq!(
        escape("0000000000000001  \\ "),
        Some(EntryError::Escape(18))
    );
    assert_eq!(
        escape("0000000000000001  \\é"),
        Some(EntryError::Escape(18))
    );
    assert_eq!(
        escape("0000000000000001  Zoë\\x"),
        Some(EntryError::Escape(22)),
        "offsets count bytes, and ë is two bytes long"
    );
    assert_eq!(
        escape("0000000000000001  \\\\\\q\\z"),
        Some(EntryError::Escape(20)),
        "`\\\\` is a valid escape; the first unknown one is `\\q` at byte 20"
    );
    assert_eq!(
        escape("0000000000000001  \\n\\\\\\"),
        Some(EntryError::Escape(22))
    );
}

#[test]
fn parse_the_first_check_that_fails_decides() {
    let error = |line: &str| line.parse::<Entry>().err();
    assert_eq!(error("zz  "), Some(EntryError::Digest));
    assert_eq!(error("zz"), Some(EntryError::Digest));
    assert_eq!(error("0000000000000001 \\q"), Some(EntryError::Separator));
    assert_eq!(error("000000000000000\\  \\q"), Some(EntryError::Digest));
}

#[test]
fn parse_reverses_display() {
    let names = [
        "a",
        " ",
        "notes/a.txt",
        "a\\b",
        "\\",
        "\\\\",
        "\n",
        "\r\n",
        "\\n",
        "\\\n\\\r\\\\",
        "line one\nline two\n",
        "Zoë\\Århus\r",
        "ends with backslash\\",
        "0000000000000000  looks like a line",
        "🦀\n🦀",
    ];
    for (index, name) in names.into_iter().enumerate() {
        let original = entry(fnv(name.as_bytes()) ^ index as u64, name);
        let line = original.to_string();
        assert_eq!(
            line.parse::<Entry>().as_ref(),
            Ok(&original),
            "the name {name:?} was written as {line:?}"
        );
    }
}

#[test]
fn entry_error_messages() {
    assert_eq!(
        EntryError::Digest.to_string(),
        "expected 16 hexadecimal digits"
    );
    assert_eq!(
        EntryError::Separator.to_string(),
        "expected two spaces after the digest"
    );
    assert_eq!(EntryError::Name.to_string(), "the name is empty");
    assert_eq!(
        EntryError::Escape(21).to_string(),
        "unknown escape at byte 21"
    );
    assert_eq!(
        EntryError::Escape(0).to_string(),
        "unknown escape at byte 0"
    );
    let error: &dyn Error = &EntryError::Name;
    assert!(error.source().is_none());
}

// -------------------------------------------------------------- manifests

#[test]
fn read_a_manifest() {
    assert_eq!(
        read_manifest(MANIFEST.as_bytes()).unwrap(),
        manifest_entries()
    );
    assert_eq!(
        read_manifest(MANIFEST.trim_end().as_bytes()).unwrap(),
        manifest_entries(),
        "the last line may end without a line feed"
    );
    assert!(read_manifest(&b""[..]).unwrap().is_empty());
}

#[test]
fn read_accepts_any_buffered_reader() {
    let cursor = Cursor::new(MANIFEST.as_bytes().to_vec());
    assert_eq!(read_manifest(cursor).unwrap(), manifest_entries());

    // A buffer of three bytes: every line arrives in many small pieces.
    let trickle = Trickle {
        data: MANIFEST.as_bytes(),
        step: 2,
        interrupt: true,
        calls: 0,
    };
    let reader = BufReader::with_capacity(3, trickle);
    assert_eq!(read_manifest(reader).unwrap(), manifest_entries());

    let mut by_reference = MANIFEST.as_bytes();
    assert_eq!(
        read_manifest(&mut by_reference).unwrap(),
        manifest_entries()
    );
}

#[test]
fn read_handles_windows_line_endings() {
    let windows = MANIFEST.replace('\n', "\r\n");
    assert_eq!(
        read_manifest(windows.as_bytes()).unwrap(),
        manifest_entries(),
        "a carriage return in front of a line feed belongs to the line ending"
    );
    let entries = read_manifest(&b"0000000000000001  a\r"[..]).unwrap();
    assert_eq!(
        entries,
        [entry(1, "a\r")],
        "without a line feed after it, a carriage return is a character of the name"
    );
}

#[test]
fn read_skips_empty_lines_only() {
    let text = "\n\n0000000000000001  a\n\r\n\n0000000000000002  b \n\n";
    assert_eq!(
        read_manifest(text.as_bytes()).unwrap(),
        [entry(1, "a"), entry(2, "b ")],
        "empty lines are skipped; the space at the end of `b ` belongs to the name"
    );
    let blank = read_manifest(&b"0000000000000001  a\n   \n"[..]);
    assert!(
        matches!(
            blank,
            Err(ManifestError::Line {
                number: 2,
                error: EntryError::Digest
            })
        ),
        "a line of spaces is not empty, and it is not an entry: {blank:?}"
    );
}

#[test]
fn read_reports_the_line_number() {
    let text = "0000000000000001  a\n\n\r\n0000000000000002 b\n0000000000000003  c\n";
    let result = read_manifest(text.as_bytes());
    assert!(
        matches!(
            result,
            Err(ManifestError::Line {
                number: 4,
                error: EntryError::Separator
            })
        ),
        "lines are numbered from 1 and empty lines count: {result:?}"
    );
    let result = read_manifest(&b"0000000000000001  a\\q"[..]);
    assert!(
        matches!(
            result,
            Err(ManifestError::Line {
                number: 1,
                error: EntryError::Escape(19)
            })
        ),
        "{result:?}"
    );
}

#[test]
fn read_reports_io_errors() {
    let broken = BufReader::new(Broken {
        data: b"0000000000000001  a\n0000000000",
        kind: ErrorKind::ConnectionReset,
    });
    match read_manifest(broken) {
        Err(ManifestError::Io(error)) => assert_eq!(error.kind(), ErrorKind::ConnectionReset),
        other => panic!("expected ManifestError::Io, got {other:?}"),
    }
    match read_manifest(&b"0000000000000001  a\n\xff\xfe\n"[..]) {
        Err(ManifestError::Io(error)) => assert_eq!(
            error.kind(),
            ErrorKind::InvalidData,
            "input that is not UTF-8 is an I/O error of the kind InvalidData"
        ),
        other => panic!("expected ManifestError::Io, got {other:?}"),
    }
}

#[test]
fn manifest_error_messages_and_sources() {
    let line = ManifestError::Line {
        number: 3,
        error: EntryError::Name,
    };
    assert_eq!(line.to_string(), "line 3 of the manifest is not valid");
    let source = line.source().expect("the EntryError is the source");
    assert_eq!(source.downcast_ref::<EntryError>(), Some(&EntryError::Name));
    assert!(source.source().is_none());

    let io = ManifestError::Io(io::Error::new(ErrorKind::TimedOut, "too slow"));
    assert_eq!(io.to_string(), "cannot read the manifest");
    let source = io.source().expect("the io::Error is the source");
    let inner = source
        .downcast_ref::<io::Error>()
        .expect("the source is the io::Error itself");
    assert_eq!(inner.kind(), ErrorKind::TimedOut);
    assert_eq!(inner.to_string(), "too slow");
}

#[test]
fn manifest_error_converts_from_io_error() {
    fn first_name(mut reader: impl BufRead) -> Result<String, ManifestError> {
        // Both `?` convert: an io::Error here, a ManifestError below.
        let mut probe = [0u8; 0];
        reader.read_exact(&mut probe)?;
        let entries = read_manifest(reader)?;
        Ok(entries
            .first()
            .map(|entry| entry.name.clone())
            .unwrap_or_default())
    }
    assert_eq!(first_name(MANIFEST.as_bytes()).unwrap(), "notes/a.txt");
    let converted: ManifestError = io::Error::new(ErrorKind::BrokenPipe, "gone").into();
    assert!(matches!(converted, ManifestError::Io(error) if error.kind() == ErrorKind::BrokenPipe));

    fn boxed(text: &str) -> Result<usize, Box<dyn Error + Send + Sync>> {
        Ok(read_manifest(text.as_bytes())?.len())
    }
    assert_eq!(boxed(MANIFEST).unwrap(), 3);
    assert_eq!(
        boxed("x").unwrap_err().to_string(),
        "line 1 of the manifest is not valid"
    );
}

#[test]
fn write_a_manifest() {
    let mut out = Vec::new();
    write_manifest(&mut out, &manifest_entries()).unwrap();
    assert_eq!(String::from_utf8(out).unwrap(), MANIFEST);

    let mut out = Vec::new();
    write_manifest(&mut out, &[]).unwrap();
    assert!(out.is_empty(), "no entries, no bytes");

    let mut out = Cursor::new(Vec::new());
    write_manifest(&mut out, &[entry(255, "a\\b\n")]).unwrap();
    assert_eq!(out.into_inner(), b"00000000000000ff  a\\\\b\\n\n");
}

#[test]
fn write_then_read_gives_the_entries_back() {
    let entries = vec![
        entry(0, "plain"),
        entry(u64::MAX, "with\nline feed"),
        entry(7, "back\\slash and \r"),
        entry(8, " spaces "),
        entry(9, "Zoë/李"),
    ];
    let mut out = Vec::new();
    write_manifest(&mut out, &entries).unwrap();
    assert_eq!(
        out.iter().filter(|&&byte| byte == b'\n').count(),
        5,
        "one line feed per entry"
    );
    assert_eq!(read_manifest(&out[..]).unwrap(), entries);
}

#[test]
fn write_repeats_short_writes() {
    for interrupt in [false, true] {
        let mut out = Stingy {
            interrupt,
            ..Stingy::default()
        };
        write_manifest(&mut out, &manifest_entries()).unwrap();
        assert_eq!(
            String::from_utf8_lossy(&out.written),
            MANIFEST,
            "this writer takes at most 3 bytes per call{}. `write` returns how many bytes it \
             took; the rest must be offered again.",
            if interrupt {
                " and is interrupted every second call"
            } else {
                ""
            }
        );
        assert_eq!(
            out.flushes, 0,
            "write_manifest leaves flushing to the caller"
        );
    }
}

#[test]
fn write_returns_errors() {
    let mut full = Full {
        room: 40,
        kind: Some(ErrorKind::PermissionDenied),
    };
    let result = write_manifest(&mut full, &manifest_entries());
    assert_eq!(
        result.map_err(|error| error.kind()),
        Err(ErrorKind::PermissionDenied)
    );

    // A loop that offers the rest again and again would never end here.
    let result = within(
        10,
        "write_manifest to a writer that takes no more bytes. A `write` that returns \
         Ok(0) can never make progress, so the writing must end with an error; \
         write_manifest",
        || {
            let mut closed = Full {
                room: 40,
                kind: None,
            };
            write_manifest(&mut closed, &manifest_entries()).map_err(|error| error.kind())
        },
    );
    assert_eq!(
        result,
        Err(ErrorKind::WriteZero),
        "a writer that takes no bytes at all cannot make progress; that is an error"
    );
}

