#[test]
fn check_all_reports_in_entry_order() {
    for workers in [0, 1, 2, 3, 7, 8, 100] {
        let statuses = within(20, "check_all", move || {
            let files = files();
            check_all(&file_entries(), workers, |name| {
                files
                    .get(name)
                    .copied()
                    .ok_or_else(|| io::Error::from(ErrorKind::NotFound))
            })
        });
        assert_eq!(
            statuses,
            file_statuses(),
            "with workers = {workers}: status number i belongs to entry number i"
        );
    }
}

#[test]
fn check_all_keeps_entry_order_when_files_finish_out_of_order() {
    /// A reader that takes its time before the first byte.
    struct Delayed {
        wait: Duration,
        data: Cursor<Vec<u8>>,
    }
    impl Read for Delayed {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            thread::sleep(std::mem::take(&mut self.wait));
            self.data.read(buf)
        }
    }
    for workers in [2, 3, 5] {
        let statuses = within(20, "check_all", move || {
            let entries: Vec<Entry> = (0..15).map(|i| entry(0, &format!("file{i:02}"))).collect();
            check_all(&entries, workers, |name| {
                // Every third file is slow, so its worker finishes it after
                // other workers have finished later entries.
                let slow = name.ends_with(['0', '3', '6', '9']);
                Ok(Delayed {
                    wait: Duration::from_millis(if slow { 25 } else { 0 }),
                    data: Cursor::new(name.as_bytes().to_vec()),
                })
            })
        });
        let expected: Vec<Status> = (0..15)
            .map(|i| Status::Changed(fnv(format!("file{i:02}").as_bytes())))
            .collect();
        assert_eq!(
            statuses, expected,
            "with workers = {workers}: the statuses must be in the order of the entries, not \
             in the order in which the workers finished them"
        );
    }
}

#[test]
fn check_all_without_entries() {
    let statuses = within(20, "check_all", || {
        check_all(&[], 4, |name| -> io::Result<io::Empty> {
            panic!("there is nothing to open, but {name:?} was opened")
        })
    });
    assert!(statuses.is_empty());
}

#[test]
fn check_all_opens_every_entry_once() {
    let mut opened = within(20, "check_all", || {
        let entries: Vec<Entry> = (0..200).map(|i| entry(i, &format!("file{i:03}"))).collect();
        let opened = Mutex::new(Vec::new());
        let statuses = check_all(&entries, 4, |name| {
            opened.lock().unwrap().push(name.to_string());
            Ok(Cursor::new(name.as_bytes().to_vec()))
        });
        for (index, status) in statuses.iter().enumerate() {
            let name = format!("file{index:03}");
            assert_eq!(*status, Status::Changed(fnv(name.as_bytes())));
        }
        opened.into_inner().unwrap()
    });
    opened.sort();
    let expected: Vec<String> = (0..200).map(|i| format!("file{i:03}")).collect();
    assert_eq!(opened, expected, "every name is opened exactly once");
}

#[test]
fn check_all_reports_open_and_read_errors() {
    let statuses = within(20, "check_all", || {
        let entries = [
            entry(0, "locked"),
            entry(0, "breaks"),
            entry(fnv(b"fine"), "fine"),
            entry(0, "gone"),
        ];
        check_all(&entries, 2, |name| match name {
            "locked" => Err(io::Error::from(ErrorKind::PermissionDenied)),
            "gone" => Err(io::Error::from(ErrorKind::NotFound)),
            "breaks" => Ok(Broken {
                data: b"some bytes, then",
                kind: ErrorKind::TimedOut,
            }),
            _ => Ok(Broken {
                data: b"",
                kind: ErrorKind::Other,
            }),
        })
    });
    assert_eq!(
        statuses,
        [
            Status::Unreadable(ErrorKind::PermissionDenied),
            Status::Unreadable(ErrorKind::TimedOut),
            Status::Unreadable(ErrorKind::Other),
            Status::Unreadable(ErrorKind::NotFound),
        ],
        "an error from `open` and an error in the middle of reading both give Unreadable"
    );
}

#[test]
fn check_all_takes_readers_that_cannot_change_threads() {
    /// `Rc` is not `Send`, so this reader must stay on the thread that
    /// opened it. The test compiles because `check_all` asks for `R: Read`
    /// and nothing more.
    struct Local {
        data: Rc<Vec<u8>>,
        at: usize,
    }
    impl Read for Local {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            let count = (&self.data[self.at..]).read(buf)?;
            self.at += count;
            Ok(count)
        }
    }
    let statuses = within(20, "check_all", || {
        let entries: Vec<Entry> = (0..40u8).map(|i| entry(fnv(&[i; 300]), "x")).collect();
        let next = AtomicUsize::new(0);
        let statuses = check_all(&entries, 3, |_| {
            let _ = next.fetch_add(1, Ordering::Relaxed);
            Ok(Local {
                data: Rc::new(Vec::new()),
                at: 0,
            })
        });
        statuses.len()
    });
    assert_eq!(statuses, 40);
}

#[test]
fn check_dir_reads_files() {
    let root: PathBuf =
        std::env::temp_dir().join(format!("seal-checkpoint-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(root.join("notes")).unwrap();
    std::fs::write(root.join("notes").join("a.txt"), b"a").unwrap();
    std::fs::write(root.join("Zo\u{eb}.bin"), [7u8; 50_000]).unwrap();
    std::fs::write(root.join("empty"), b"").unwrap();
    std::fs::write(root.join("changed"), b"new text").unwrap();

    let entries = [
        entry(fnv(b"a"), "notes/a.txt"),
        entry(fnv(&[7u8; 50_000]), "Zo\u{eb}.bin"),
        entry(fnv(b""), "empty"),
        entry(fnv(b"old text"), "changed"),
        entry(0, "notes/missing.txt"),
    ];
    let expected = [
        Status::Match,
        Status::Match,
        Status::Match,
        Status::Changed(fnv(b"new text")),
        Status::Unreadable(ErrorKind::NotFound),
    ];
    for workers in [1, 3] {
        let (root, entries) = (root.clone(), entries.clone());
        let statuses = within(20, "check_dir", move || check_dir(&root, &entries, workers));
        assert_eq!(statuses, expected, "with workers = {workers}");
    }
    let _ = std::fs::remove_dir_all(&root);
}

// --------------------------------------------------------------- block_on

/// Returns `Pending` for the given number of polls and asks to be polled
/// again each time, from inside `poll`.
struct Again(u32);

impl Future for Again {
    type Output = &'static str;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<&'static str> {
        if self.0 == 0 {
            return Poll::Ready("done");
        }
        self.0 -= 1;
        cx.waker().wake_by_ref();
        Poll::Pending
    }
}

/// Completes when another thread has set a flag. That thread starts at the
/// first poll, waits a moment, sets the flag and uses the waker.
struct Later {
    done: Arc<AtomicBool>,
    started: bool,
    wait: Duration,
    keep: Arc<Mutex<Option<Waker>>>,
}

impl Later {
    fn after(wait: Duration) -> Later {
        Later {
            done: Arc::new(AtomicBool::new(false)),
            started: false,
            wait,
            keep: Arc::new(Mutex::new(None)),
        }
    }
}

impl Future for Later {
    type Output = u32;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<u32> {
        if self.done.load(Ordering::SeqCst) {
            return Poll::Ready(7);
        }
        if !self.started {
            self.started = true;
            let (done, wait, waker) = (Arc::clone(&self.done), self.wait, cx.waker().clone());
            *self.keep.lock().unwrap() = Some(waker.clone());
            thread::spawn(move || {
                thread::sleep(wait);
                done.store(true, Ordering::SeqCst);
                waker.wake();
            });
        }
        Poll::Pending
    }
}

#[test]
fn block_on_returns_the_output() {
    let result = within(20, "block_on", || {
        let number = block_on(async { 6 * 7 });
        let text = block_on(std::future::ready(String::from("ready")));
        (number, text)
    });
    assert_eq!(result, (42, "ready".to_string()));
}

#[test]
fn block_on_runs_async_functions_that_await() {
    async fn double(n: u32) -> u32 {
        n * 2
    }
    async fn sum(limit: u32) -> u32 {
        let mut total = 0;
        for n in 0..limit {
            total += double(n).await;
            Again(1).await;
        }
        total
    }
    assert_eq!(within(20, "block_on", || block_on(sum(100))), 9900);
}

#[test]
fn block_on_takes_futures_that_borrow_and_are_not_send() {
    let length = within(20, "block_on", || {
        let local = Rc::new(String::from("borrowed"));
        let text = &local;
        // The future borrows a local variable and holds an Rc across an
        // await, so it is neither 'static nor Send.
        let result: Rc<String> = block_on(async {
            let copy = Rc::clone(text);
            Again(2).await;
            copy
        });
        result.len()
    });
    assert_eq!(length, 8);
}

#[test]
fn block_on_polls_again_after_a_wake_from_inside_poll() {
    assert_eq!(within(20, "block_on", || block_on(Again(3))), "done");
    assert_eq!(within(20, "block_on", || block_on(Again(0))), "done");
}

#[test]
fn block_on_sleeps_until_another_thread_wakes_it() {
    let value = within(20, "block_on", || {
        block_on(Later::after(Duration::from_millis(50)))
    });
    assert_eq!(value, 7);
}

#[test]
fn block_on_wakers_may_be_used_afterwards() {
    let values = within(20, "block_on", || {
        let first = Later::after(Duration::from_millis(1));
        let keep = Arc::clone(&first.keep);
        let a = block_on(first);
        // The future is gone; its waker is still here. Using it now, also
        // from another thread, must do no harm to the next `block_on`.
        let old = keep
            .lock()
            .unwrap()
            .take()
            .expect("the first poll kept a waker");
        old.wake_by_ref();
        let clone = old.clone();
        thread::spawn(move || clone.wake()).join().unwrap();
        let b = block_on(Later::after(Duration::from_millis(20)));
        old.wake();
        let c = block_on(async { 1 });
        (a, b, c)
    });
    assert_eq!(values, (7, 7, 1));
}

// ---------------------------------------------------------- in_background

#[test]
fn in_background_gives_the_result_of_the_work() {
    let (number, text) = within(20, "block_on(in_background(..))", || {
        let number = block_on(in_background(|| 6 * 7));
        let words = ["moved", "into", "the", "work"];
        let text = block_on(in_background(move || words.join(" ")));
        (number, text)
    });
    assert_eq!(number, Ok(42));
    assert_eq!(text, Ok("moved into the work".to_string()));
}

#[test]
fn in_background_runs_on_another_thread() {
    let here = thread::current().id();
    let there = within(20, "block_on(in_background(..))", || {
        block_on(in_background(|| thread::current().id()))
    });
    assert_ne!(
        there,
        Ok(here),
        "the work must not run on the thread that waits for it"
    );
}

#[test]
fn in_background_starts_without_being_polled() {
    let result = within(20, "in_background", || {
        let (sender, receiver) = mpsc::channel();
        let job = in_background(move || sender.send("started").is_ok());
        assert_eq!(
            receiver.recv_timeout(Duration::from_secs(10)),
            Ok("started"),
            "the work starts when in_background is called, not when the future is first polled"
        );
        block_on(job)
    });
    assert_eq!(result, Ok(true));
}

#[test]
fn in_background_returns_while_the_work_is_still_running() {
    let value = within(20, "in_background", || {
        let (release, gate) = mpsc::channel::<u8>();
        // If `in_background` waited for the work, this would never get to
        // the `send` below.
        let job = in_background(move || gate.recv().unwrap_or(0));
        release.send(9).unwrap();
        block_on(job)
    });
    assert_eq!(value, Ok(9));
}

#[test]
fn in_background_turns_a_panic_into_an_error() {
    let result = within(20, "block_on(in_background(..))", || {
        block_on(in_background(|| -> u32 {
            // Like `panic!`, without the message on standard error.
            std::panic::resume_unwind(Box::new("the work failed"))
        }))
    });
    assert_eq!(
        result,
        Err(Panicked),
        "a panic in the work must end the future with Err(Panicked)"
    );
    assert_eq!(Panicked.to_string(), "background work panicked");
    let error: Box<dyn Error + Send + Sync> = Box::new(Panicked);
    assert!(error.source().is_none());
}

#[test]
fn in_background_jobs_can_be_awaited_in_any_order() {
    let result = within(20, "awaiting three background jobs", || {
        block_on(async {
            let (release, gate) = mpsc::channel::<()>();
            let slow = in_background(move || {
                let _ = gate.recv();
                "slow"
            });
            let quick = in_background(|| "quick");
            let other = in_background(|| String::from("other"));
            let second = quick.await.unwrap();
            let third = other.await.unwrap();
            release.send(()).unwrap();
            let first = slow.await.unwrap();
            format!("{first} {second} {third}")
        })
    });
    assert_eq!(result, "slow quick other");
}

// ------------------------------------------------------------- digest_all

#[test]
fn digest_all_keeps_the_order_of_the_readers() {
    let digests = within(20, "block_on(digest_all(..))", || {
        let readers: Vec<Cursor<Vec<u8>>> = (0..20u8)
            .map(|i| Cursor::new(vec![i; usize::from(i) * 1000]))
            .collect();
        block_on(digest_all(readers))
    });
    assert_eq!(digests.len(), 20, "one result for each of the 20 readers");
    for (i, result) in (0..20u8).zip(digests) {
        assert_eq!(result.ok(), Some(fnv(&vec![i; usize::from(i) * 1000])));
    }
}

#[test]
fn digest_all_without_readers() {
    let digests = within(20, "block_on(digest_all(..))", || {
        block_on(digest_all(Vec::<io::Empty>::new()))
    });
    assert!(digests.is_empty());
}

#[test]
fn digest_all_reports_errors_and_panics_in_place() {
    struct Moody(u8);
    impl Read for Moody {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            match self.0 {
                0 => Ok(0),
                1 => Err(io::Error::from(ErrorKind::PermissionDenied)),
                2 => std::panic::resume_unwind(Box::new("the reader failed")),
                _ => {
                    self.0 = 0;
                    buf[0] = b'a';
                    Ok(1)
                }
            }
        }
    }
    let kinds = within(20, "block_on(digest_all(..))", || {
        let readers = vec![Moody(3), Moody(1), Moody(2), Moody(0), Moody(2)];
        block_on(digest_all(readers))
            .into_iter()
            .map(|result| result.map_err(|error| error.kind()))
            .collect::<Vec<_>>()
    });
    assert_eq!(
        kinds,
        [
            Ok(fnv(b"a")),
            Err(ErrorKind::PermissionDenied),
            Err(ErrorKind::Other),
            Ok(fnv(b"")),
            Err(ErrorKind::Other),
        ],
        "a reader that panics gives an io::Error of the kind Other, at its own position"
    );
}
